//! 🧭️ One original schema stack selection is recorded before a later paid update.
use super::*;
use semio_framework_value_native_decoding::native_decoding::{OriginalEffectReply,OriginalEffectReplyComplete};

impl<I:NativeValueSource+?Sized> NativeRecordMatcher<I>{
 /// 📐️ Quotes the exact last-frame lookup and its resident selection/reply headers.
 pub fn capture_frame_demand(&self)->Result<RetirementDemand,ValueError>{if self.closing||self.done||self.key.is_none()||self.pending.is_some()||self.leaf.is_some()||self.scan.is_some()||self.frames.is_empty()||!self.key_backing.initialized(){return Err(invalid())}let index=self.frames.len()-1;let depth=page(self.frames.next_get_depth_demand(index))?.max(1);let copy_bytes=size_of::<Option<(usize,SchemaFrame)>>().checked_add(size_of::<Option<Result<RetainedCloneStep,ValueError>>>()).ok_or_else(invalid)?;Ok(RetirementDemand{copy_bytes,depth,..Default::default()})}
 /// ⏱️ Quotes native traversal, resident selection and the borrowed reply.
 pub fn capture_frame_work_demand(&self)->Result<u64,ValueError>{self.capture_frame_demand()?;page(self.frames.get_source_work_demand(self.frames.len()-1))?.checked_add(2).ok_or_else(invalid)}
 /// 📥️ Captures the same last stack frame without invoking any user callback.
 pub fn capture_frame_into<'r>(&mut self,effect:&mut engine::RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,RetainedCloneStep,ValueError>)->Result<OriginalEffectReplyComplete<'r,RetainedCloneStep,ValueError>,ValueError>{let demand=self.capture_frame_demand()?;let work=self.capture_frame_work_demand()?;self.key_backing.validate_effect(effect)?;if !retained_clone_grant_admits(effect.grant(),demand)||effect.remaining_work_units()?<work{return Ok(reply.complete(Ok(RetainedCloneStep::Progress(Default::default()))))}let index=self.frames.len()-1;let quote=page(self.frames.get_source_work_demand(index))?;let turn=self.frames.get_source_step(index,quote);if !effect.performed(u64::try_from(turn.work).map_err(|_|invalid())?)?{return Ok(reply.complete(Err(reply_failure(ValueError::literal(ValueRefusalKind::WorkLimit,"schema frame lookup exceeded Work")))))}let selected=match turn.result{Ok(Some(frame))=>*frame,Ok(None)=>{let _=effect.performed(1)?;return Ok(reply.complete(Err(reply_failure(invalid()))))},Err(error)=>{let _=effect.performed(1)?;return Ok(reply.complete(Err(reply_failure(error.into()))))}};if !effect.performed(2)?{return Ok(reply.complete(Err(reply_failure(ValueError::literal(ValueRefusalKind::WorkLimit,"schema frame capture exceeded Work")))))}self.scan=Some((index,selected));Ok(reply.complete(Ok(RetainedCloneStep::Progress(receipt(demand)))))}
}

fn reply_failure(error:ValueError)->ValueError{error.with_retained_progress(RetainedCloneProgress{copied_items:1,copied_bytes:size_of::<Option<Result<RetainedCloneStep,ValueError>>>(),..Default::default()})}
impl<I:NativeValueSource+?Sized> NativeRecordMatcher<I>{
 /// 👁️ Selects stack removal only from the actual resident captured frame.
 pub fn captured_frame_needs_pop(&self)->Result<bool,ValueError>{let(index,frame)=self.scan.ok_or_else(invalid)?;if self.closing||self.pending.is_some()||self.leaf.is_some()||index.checked_add(1)!=Some(self.frames.len()){return Err(invalid())}Ok(frame.role!=2&&frame.index>=frame.count)}
 /// 📐️ Quotes the selected native frame update and all possible resident headers.
 pub fn apply_frame_demand(&self)->Result<RetirementDemand,ValueError>{if self.captured_frame_needs_pop()?{return Err(invalid())}let(index,_)=self.scan.ok_or_else(invalid)?;let depth=page(self.frames.next_get_depth_demand(index))?.max(1);let sizes=[size_of::<SchemaFrame>(),size_of::<Option<(usize,SchemaFrame)>>(),size_of::<Option<SchemaFrame>>(),size_of::<Option<NativeSchemaLeaf>>(),2*size_of::<usize>(),size_of::<NativeFieldMatch>(),size_of::<Option<Result<RetainedCloneStep,ValueError>>>()];let copy_bytes=sizes.into_iter().try_fold(0usize,|sum,size|sum.checked_add(size)).ok_or_else(invalid)?;Ok(RetirementDemand{copy_bytes,depth,..Default::default()})}
 /// ⏱️ Bounds native lookup, descriptor selection and resident header writes.
 pub fn apply_frame_work_demand(&self)->Result<u64,ValueError>{self.apply_frame_demand()?;let(index,_)=self.scan.ok_or_else(invalid)?;page(self.frames.get_source_work_demand(index))?.checked_add(9).ok_or_else(invalid)}
 /// 🧩️ Applies one selected native schema node under the same performed Work receipt.
 pub fn apply_frame_into<'r>(&mut self,effect:&mut engine::RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,RetainedCloneStep,ValueError>)->Result<OriginalEffectReplyComplete<'r,RetainedCloneStep,ValueError>,ValueError>{let demand=self.apply_frame_demand()?;let work=self.apply_frame_work_demand()?;self.key_backing.validate_effect(effect)?;if !retained_clone_grant_admits(effect.grant(),demand)||effect.remaining_work_units()?<work{return Ok(reply.complete(Ok(RetainedCloneStep::Progress(Default::default()))))}let(index,mut frame)=self.scan.ok_or_else(invalid)?;let mut matched=self.matched;let mut changed_match=false;let mut leaf=None;let mut pending=None;let mut leaf_root=0usize;if frame.role==2{frame.best=alternative(frame.best,matched);frame.role=1;matched=NativeFieldMatch::Missing;changed_match=true}else{if !effect.performed(1)?{return Ok(reply.complete(Err(reply_failure(ValueError::literal(ValueRefusalKind::WorkLimit,"schema descriptor read exceeded Work")))))}let entry=frame.index;let root=frame.root.unwrap_or(entry);let Some(node)=(frame.fields.read)(entry)else{let error=invalid();let _=effect.performed(1)?;return Ok(reply.complete(Err(reply_failure(error))))};frame.index=frame.index.checked_add(1).ok_or_else(invalid)?;if frame.role==1{frame.role=2;matched=NativeFieldMatch::Missing;changed_match=true}match node{NativeRecordSchema::Leaf(value)=>{leaf=Some(value);leaf_root=root},NativeRecordSchema::Flatten{fields,count}=>pending=Some(SchemaFrame{fields,count,index:0,root:Some(root),role:0,before:NativeFieldMatch::Missing,best:NativeFieldMatch::Missing}),NativeRecordSchema::Union{fields,count}=>{pending=Some(SchemaFrame{fields,count,index:0,root:Some(root),role:1,before:matched,best:NativeFieldMatch::Missing});matched=NativeFieldMatch::Missing;changed_match=true},NativeRecordSchema::Skip=>{}}}let quote=page(self.frames.get_source_work_demand(index))?;let turn=self.frames.get_mut_source_step(index,quote);if !effect.performed(u64::try_from(turn.work).map_err(|_|invalid())?)?{return Ok(reply.complete(Err(reply_failure(ValueError::literal(ValueRefusalKind::WorkLimit,"schema frame lookup exceeded Work")))))}let target=match turn.result{Ok(Some(target))=>target,Ok(None)=>{let _=effect.performed(1)?;return Ok(reply.complete(Err(reply_failure(invalid()))))},Err(error)=>{let _=effect.performed(1)?;return Ok(reply.complete(Err(reply_failure(error.into()))))}};let writes=3u64+u64::from(changed_match)+(if leaf.is_some(){3}else{0})+u64::from(pending.is_some());if !effect.performed(writes)?{return Ok(reply.complete(Err(reply_failure(ValueError::literal(ValueRefusalKind::WorkLimit,"schema frame update exceeded Work")))))}*target=frame;self.scan=None;let mut copied=size_of::<SchemaFrame>()+size_of::<Option<(usize,SchemaFrame)>>() + size_of::<Option<Result<RetainedCloneStep,ValueError>>>();if changed_match{self.matched=matched;copied+=size_of::<NativeFieldMatch>()}if let Some(value)=leaf{self.leaf=Some(value);self.leaf_root=leaf_root;self.offset=0;copied+=size_of::<Option<NativeSchemaLeaf>>()+2*size_of::<usize>()}if let Some(value)=pending{self.pending=Some(value);copied+=size_of::<Option<SchemaFrame>>()}Ok(reply.complete(Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,copied_bytes:copied,..Default::default()}))))}
}

impl<I:NativeValueSource+?Sized> NativeRecordMatcher<I>{
 /// 📐️ Quotes the same original selected tail and its resident destination.
 pub fn pop_frame_demand(&self)->Result<RetirementDemand,ValueError>{if !self.captured_frame_needs_pop()?||self.popped.is_some(){return Err(invalid())}page(self.frames.pop_source_demand())}
 /// ⏱️ Quotes every original radix step of the selected tail pop.
 pub fn pop_frame_work_demand(&self)->Result<u64,ValueError>{self.pop_frame_demand()?;page(self.frames.pop_source_work_demand())}
 /// 📤️ Moves the selected original frame into its private resident slot.
 pub fn pop_frame_into<'r>(&mut self,effect:&mut engine::RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,RetainedCloneStep,ValueError>)->Result<OriginalEffectReplyComplete<'r,RetainedCloneStep,ValueError>,ValueError>{self.pop_frame_demand()?;self.key_backing.validate_effect(effect)?;self.frames.pop_into(&mut self.popped,effect,reply.progress())}
 fn popped_selection(&self)->Result<SchemaFrame,ValueError>{let(index,captured)=self.scan.ok_or_else(invalid)?;let popped=self.popped.ok_or_else(invalid)?;if self.closing||index!=self.frames.len()||captured.count!=popped.count||captured.index!=popped.index||captured.root!=popped.root||captured.role!=popped.role||captured.before!=popped.before||captured.best!=popped.best{return Err(invalid())}Ok(popped)}
 /// 📐️ Quotes clearing the original pop and applying its selected union result.
 pub fn finish_popped_demand(&self)->Result<RetirementDemand,ValueError>{let frame=self.popped_selection()?;let mut copy=size_of::<Option<SchemaFrame>>().checked_add(size_of::<Option<(usize,SchemaFrame)>>()).and_then(|value|value.checked_add(size_of::<Option<Result<RetainedCloneStep,ValueError>>>())).ok_or_else(invalid)?;if frame.role==1{copy=copy.checked_add(size_of::<NativeFieldMatch>()).ok_or_else(invalid)?;if combined(frame.before,frame.best)==NativeFieldMatch::Ambiguous{copy=copy.checked_add(size_of::<bool>()).ok_or_else(invalid)?}}Ok(fixed(copy))}
 /// ⏱️ Quotes the original pop/selection clear and any selected union metadata.
 pub fn finish_popped_work_demand(&self)->Result<u64,ValueError>{let frame=self.popped_selection()?;Ok(3+u64::from(frame.role==1)+u64::from(frame.role==1&&combined(frame.before,frame.best)==NativeFieldMatch::Ambiguous))}
 /// ✅️ Applies the selected union result and retires only the native copied headers.
 pub fn finish_popped_into<'r>(&mut self,effect:&mut engine::RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,RetainedCloneStep,ValueError>)->Result<OriginalEffectReplyComplete<'r,RetainedCloneStep,ValueError>,ValueError>{let demand=self.finish_popped_demand()?;let work=self.finish_popped_work_demand()?;self.key_backing.validate_effect(effect)?;if !retained_clone_grant_admits(effect.grant(),demand)||effect.remaining_work_units()?<work{return Ok(reply.complete(Ok(RetainedCloneStep::Progress(Default::default()))))}let frame=self.popped_selection()?;if !effect.performed(work)?{return Ok(reply.complete(Err(reply_failure(ValueError::literal(ValueRefusalKind::WorkLimit,"schema frame pop completion exceeded Work")))))}self.popped=None;self.scan=None;if frame.role==1{self.matched=combined(frame.before,frame.best);if self.matched==NativeFieldMatch::Ambiguous{self.done=true}}Ok(reply.complete(Ok(RetainedCloneStep::Progress(receipt(demand)))))}
}

impl<I:NativeValueSource+?Sized> NativeRecordMatcher<I>{
 /// 📐️ Quotes the actual resident leaf and match headers plus its borrowed reply.
 pub fn compare_leaf_demand(&self,body:usize)->Result<RetirementDemand,ValueError>{if self.closing||self.done||self.key.is_none()||self.leaf.is_none()||self.pending.is_some()||self.scan.is_some()||self.popped.is_some()||!self.key_backing.initialized(){return Err(invalid())}if body==0{return Ok(Default::default())}let sizes=[size_of::<Option<NativeSchemaLeaf>>(),size_of::<usize>(),size_of::<NativeFieldMatch>(),size_of::<bool>(),size_of::<Option<Result<RetainedCloneStep,ValueError>>>()];let copy_bytes=sizes.into_iter().try_fold(0usize,|sum,size|sum.checked_add(size)).ok_or_else(invalid)?;Ok(fixed(copy_bytes))}
 /// ⏱️ Bounds one metadata check, actual compared bytes and the selected native writes.
 pub fn compare_leaf_work_demand(&self,body:usize)->Result<u64,ValueError>{self.compare_leaf_demand(body)?;if body==0{return Ok(0)}let leaf=self.leaf.ok_or_else(invalid)?;let bytes=match self.key.ok_or_else(invalid)?{Key::Ordinal(_)=>0,Key::Name(pointer)=>{let key=unsafe{&*pointer};if key.len()!=leaf.name.len(){0}else{if self.offset>key.len(){return Err(invalid())}body.min(64).min(key.len()-self.offset)}}};u64::try_from(bytes).ok().and_then(|value|value.checked_add(5)).ok_or_else(invalid)}
 /// 🔎️ Compares only the funded prefix of the same original key before paid metadata changes.
 pub fn compare_leaf_into<'r>(&mut self,body:usize,effect:&mut engine::RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,RetainedCloneStep,ValueError>)->Result<OriginalEffectReplyComplete<'r,RetainedCloneStep,ValueError>,ValueError>{let demand=self.compare_leaf_demand(body)?;let work=self.compare_leaf_work_demand(body)?;self.key_backing.validate_effect(effect)?;if body==0||!retained_clone_grant_admits(effect.grant(),demand)||effect.remaining_work_units()?<work{return Ok(reply.complete(Ok(RetainedCloneStep::Progress(Default::default()))))}if !effect.performed(1)?{return Ok(reply.complete(Err(reply_failure(ValueError::literal(ValueRefusalKind::WorkLimit,"schema leaf check exceeded Work")))))}let leaf=self.leaf.ok_or_else(invalid)?;let mut next_offset=self.offset;let matched=match self.key.ok_or_else(invalid)?{Key::Ordinal(value)=>Some(value==leaf.ordinal),Key::Name(pointer)=>{let key=unsafe{&*pointer}.as_bytes();let name=leaf.name.as_bytes();if key.len()!=name.len(){Some(false)}else{let end=self.offset.checked_add(body.min(64).min(key.len()-self.offset)).ok_or_else(invalid)?;let mut equal=true;for index in self.offset..end{if !effect.performed(1)?{return Ok(reply.complete(Err(reply_failure(ValueError::literal(ValueRefusalKind::WorkLimit,"schema key comparison exceeded Work")))))}if key[index]!=name[index]{equal=false;break}}if !equal{Some(false)}else if end==key.len(){Some(true)}else{next_offset=end;None}}}};let next_match=if matched==Some(true){match self.matched{NativeFieldMatch::Missing=>NativeFieldMatch::Field(self.leaf_root),_=>NativeFieldMatch::Ambiguous}}else{self.matched};let changes_match=matched==Some(true);let changes_done=changes_match&&next_match==NativeFieldMatch::Ambiguous;let writes=2u64+u64::from(changes_match)+u64::from(changes_done);if !effect.performed(writes)?{return Ok(reply.complete(Err(reply_failure(ValueError::literal(ValueRefusalKind::WorkLimit,"schema leaf update exceeded Work")))))}let mut copied=size_of::<Option<Result<RetainedCloneStep,ValueError>>>();if matched.is_some(){self.leaf=None;copied+=size_of::<Option<NativeSchemaLeaf>>()}else{self.offset=next_offset;copied+=size_of::<usize>()}if changes_match{self.matched=next_match;copied+=size_of::<NativeFieldMatch>()}if changes_done{self.done=true;copied+=size_of::<bool>()}let progress=RetainedCloneProgress{copied_items:1,copied_bytes:copied,..Default::default()};Ok(reply.complete(Ok(if self.done{RetainedCloneStep::Complete(progress)}else{RetainedCloneStep::Progress(progress)})))}
}

impl<I:NativeValueSource+?Sized> NativeRecordMatcher<I>{
 /// 📐️ Quotes the terminal matcher flag and borrowed reply.
 pub fn finish_match_demand(&self)->Result<RetirementDemand,ValueError>{if self.closing||self.done||self.key.is_none()||self.pending.is_some()||self.scan.is_some()||self.popped.is_some()||self.leaf.is_some()||!self.frames.is_empty()||!self.key_backing.initialized(){return Err(invalid())}Ok(fixed(size_of::<bool>()+size_of::<Option<Result<RetainedCloneStep,ValueError>>>()))}
 /// 🏁️ Publishes completion only after every original descriptor frame is drained.
 pub fn finish_match_into<'r>(&mut self,effect:&mut engine::RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,RetainedCloneStep,ValueError>)->Result<OriginalEffectReplyComplete<'r,RetainedCloneStep,ValueError>,ValueError>{let demand=self.finish_match_demand()?;self.key_backing.validate_effect(effect)?;if !retained_clone_grant_admits(effect.grant(),demand)||effect.remaining_work_units()?<2{return Ok(reply.complete(Ok(RetainedCloneStep::Progress(Default::default()))))}if !effect.performed(2)?{return Ok(reply.complete(Err(reply_failure(ValueError::literal(ValueRefusalKind::WorkLimit,"schema match completion exceeded Work")))))}self.done=true;Ok(reply.complete(Ok(RetainedCloneStep::Complete(receipt(demand)))))}
}

/// 🎛️ Identifies the next actual nested action or bounded native matcher leaf.
#[derive(Clone,Copy,Debug,PartialEq,Eq)]pub enum NativeSchemaMatchSelection{KeyBirth,KeyStart,KeyAction,KeyMetadata(super::key::NativeSchemaKeyMetadata),KeyPost,KeyAcknowledgement,KeySettlement,KeyError,CheckpointRecovery,KeyBind,PendingSlot,CompareLeaf,CaptureFrame,ApplyFrame,PopFrame,FinishPopped,Finish,Complete}
impl<I:NativeValueSource+?Sized> NativeRecordMatcher<I>{
 /// 🧭️ Selects only from the current resident owners and frozen request state.
 pub fn selection(&self)->Result<NativeSchemaMatchSelection,ValueError>{use NativeSchemaMatchSelection as S;if self.closing{return Err(invalid())}if self.done{return Ok(S::Complete)}if !self.key_backing.initialized(){return Ok(S::KeyBirth)}let frame=self.key_backing.get().ok_or_else(invalid)?;if frame.checkpoint_unresolved(){return Ok(S::CheckpointRecovery)}if !frame.started(){return Ok(S::KeyStart)}let acknowledgement=frame.acknowledgement();if acknowledgement.source_post_pending(){return Ok(S::KeyPost)}if acknowledgement.binding_needed(){return Ok(S::KeyMetadata(super::key::NativeSchemaKeyMetadata::Bind))}if acknowledgement.metadata_close_demand().is_ok(){return Ok(S::KeyMetadata(super::key::NativeSchemaKeyMetadata::CloseMetadata))}if acknowledgement.rearm_authority_demand().is_ok(){return Ok(S::KeyMetadata(super::key::NativeSchemaKeyMetadata::Rearm))}if acknowledgement.acknowledgement_pending(){return Ok(S::KeyAcknowledgement)}if acknowledgement.acknowledgement_ready(){return Ok(S::KeySettlement)}if acknowledgement.semantic_ready(){if !acknowledgement.semantic_success_ready(){return Ok(S::KeySettlement)}if acknowledgement.authority_preparation_needed(){return Ok(S::KeyMetadata(super::key::NativeSchemaKeyMetadata::Prepare))}return Ok(S::KeyAcknowledgement)}if frame.pending(){return Ok(S::KeyAction)}if frame.request_needs_settlement(){return Ok(S::KeySettlement)}if frame.result().is_some_and(Result::is_err){return Ok(S::KeyError)}if self.key.is_none(){return if frame.key()?.is_some(){Ok(S::KeyBind)}else{Ok(S::KeyAction)}}if self.popped.is_some(){return Ok(S::FinishPopped)}if self.pending.is_some(){return Ok(S::PendingSlot)}if self.leaf.is_some(){return Ok(S::CompareLeaf)}if self.scan.is_some(){return if self.captured_frame_needs_pop()?{Ok(S::PopFrame)}else{Ok(S::ApplyFrame)}}if self.frames.is_empty(){Ok(S::Finish)}else{Ok(S::CaptureFrame)}}
}
